// Common flags: EFD_CLOEXEC, EFD_NONBLOCK
int fd_flags = EFD_CLOEXEC | EFD_NONBLOCK;

// Create event file descriptor
efd = eventfd2(initial_count, fd_flags);

// Semaphore mode (read consumes 1 instead of full count)
int sem_efd = eventfd2(1, EFD_SEMAPHORE);

